    // Assembled thoughts: a sentence put together from parts, so it comes out different nearly every time.
    // A file per raven holds templates ([theme] and the parts in order) and the lists of parts (@name).
    //   [see_enemy] {opener} {about_foe} {advice?}      — {advice?}: the part is there only sometimes
    // A part's line may hold the usual placeholders ({name}, {seen}, {seen_gen}, {friend}...); a line whose
    // placeholder has no value right now is not used, and a template that cannot be filled gives way to another.
    internal static class Patterns
    {
        internal const string HuginFile = "hugin_patterns.txt";
        internal const string MuninFile = "munin_patterns.txt";
        internal static float Share = 1f; // how often an assembled thought wins over a whole one, when both fit (the whole lines are now only a spare)

        private sealed class Book
        {
            public DateTime Stamp;
            public readonly Dictionary<string, List<string>> Templates = new Dictionary<string, List<string>>();
            public readonly Dictionary<string, List<string>> Parts = new Dictionary<string, List<string>>();
        }

        private static readonly Dictionary<string, Book> Cache = new Dictionary<string, Book>();
        private static readonly System.Random Rng = new System.Random();

        // what was said lately, per list of parts (and per theme's templates): not taken again until others had their turn,
        // so even when the opening repeats, the heart of the sentence and its end do not
        private static readonly Dictionary<List<string>, List<string>> Recent = new Dictionary<List<string>, List<string>>();

        // raw: a part as written, by the text it became after its own list was filled in ({м_слівце}): remembered as
        // written, or the same part with another word inside would pass for a new one and come again at once
        private static string Fresh(List<string> owner, List<string> fit, Dictionary<string, string> raw = null)
        {
            List<string> recent;
            if (!Recent.TryGetValue(owner, out recent)) { recent = new List<string>(); Recent[owner] = recent; }
            List<string> pool = new List<string>();
            foreach (string x in fit) if (!recent.Contains(KeyOf(x, raw))) pool.Add(x);
            if (pool.Count == 0) pool = fit;
            string pick = pool[Rng.Next(pool.Count)];
            recent.Add(KeyOf(pick, raw));
            int keep = Mathf.Clamp(fit.Count - 1, 0, 6); // up to the last 6, never all of them
            while (recent.Count > keep) recent.RemoveAt(0);
            return pick;
        }

        private static string KeyOf(string x, Dictionary<string, string> raw)
        {
            string r;
            return raw != null && raw.TryGetValue(x, out r) ? r : x;
        }

