        private static string RevisionMark { get { return "# patterns rev " + Revision + " (" + Lang.T("не видаляй: так мод знає, що вже дописав") + ")"; } } // (the prefix is read back: never translated)

        private static void Append(string path, string[] lines)
        {
            // what the file already has: templates, and the lines of each list (a line counts only in its own list)
            HashSet<string> have = new HashSet<string>();
            string section = "";
            foreach (string l in File.ReadAllLines(path, Encoding.UTF8))
            {
                if (l.StartsWith("# patterns rev " + Revision + " ")) return;
                string t = l.Trim();
                if (t.Length == 0 || t.StartsWith("#")) continue;
                if (t.StartsWith("@")) { section = t; continue; }
                if (t.StartsWith("[")) { section = ""; have.Add(t); continue; }
                have.Add(section + "\n" + t);
            }
            List<string> add = new List<string>();
            add.Add("");
            add.Add(RevisionMark);
            string header = null;
            bool headerOut = false;
            foreach (string l in lines)
            {
                string t = l.Trim();
                if (t.Length == 0) continue;
                if (t.StartsWith("@")) { header = t; headerOut = false; continue; }
                if (t.StartsWith("[")) { header = null; if (!have.Contains(t)) add.Add(t); continue; }
                if (header == null || have.Contains(header + "\n" + t)) continue;
                if (!headerOut) { add.Add(""); add.Add(header); headerOut = true; }
                add.Add(t);
            }
            File.AppendAllText(path, "\n" + string.Join("\n", add.ToArray()) + "\n", new UTF8Encoding(false));
        }

        private static void Write(string path, string who, string[] lines)
        {
            lines = Lang.Lines(Path.GetFileName(path), lines); // the current language's own lines
            if (File.Exists(path)) { Append(path, lines); return; }
            List<string> all = new List<string>();
            all.Add(Lang.F("# {0}: складені думки. Речення збирається з частин, тож щоразу виходить інше.", who));
            all.Add(Lang.T("# [тема] шаблон — частини в дужках у потрібному порядку: {звертання} {про_ворога} {порада?}"));
            all.Add(Lang.T("#   знак ? у кінці назви — частина буває не завжди. Решта тексту шаблону йде як є."));
            all.Add(Lang.T("# @назва — список частин: по одній на рядок, ворон бере навмання."));
            all.Add(Lang.T("# Підстановки в частинах: {name} — ти; {friend} — інший гравець поруч;"));
            all.Add(Lang.T("#   {seen} {seen_gen} {seen_ins} {seen_genpl} — найближчий ворог у відмінках (троль, троля, тролем, тролів); {seen_count} — скільки їх;"));
            all.Add(Lang.T("#   {biome_here} {biome_here_in} — де ти зараз (Чорний ліс / у Чорному лісі)."));
            all.Add(Lang.T("# Теми: see_enemy (вороги поруч), see_hurt (мало здоров'я), see_friend (поруч інший гравець), see_place (місцевість), see_night (ніч),"));
            all.Add(Lang.T("#   а також події: kill, kill_many, death..., near_death, boss, level, fall, build, chop, mine, fish, swim, sail, encumbered, hungry, weather_..., flee, travel, biome, dungeon, idle."));
            all.Add(Lang.T("# Підстановки подій: {top} {top_gen} {top_ins} {top_genpl} — кого вбито найбільше; {count}; {killer...} — хто вбив; {attacker...} — хто ледь не вбив; {boss...}; {fish}; {km}; {biome} {biome_in} — новий біом."));
            all.Add(Lang.T("# Про монстрів пиши без родових закінчень («здоровило», а не «великий»); про гравця — обидві форми: {зняв|зняла}, мод вибере за персонажем."));
            all.Add(Lang.T("# Рядки з # на початку пропускаються. Файл можна правити під час гри. Видалиш — мод створить заново."));
            all.Add(RevisionMark);
            all.AddRange(lines);
            File.WriteAllLines(path, all.ToArray(), new UTF8Encoding(false));
        }

        // the file's date is looked at no more than once in CheckSeconds: a single line asks for the book many times
        private const float CheckSeconds = 2f;
        private static readonly Dictionary<string, float> CheckedAt = new Dictionary<string, float>();

        private static Book Read(string path, string[] fallback)
        {
            Book b;
            float now = Time.realtimeSinceStartup, at;
            if (Cache.TryGetValue(path, out b) && CheckedAt.TryGetValue(path, out at) && now - at < CheckSeconds) return b;
            CheckedAt[path] = now;
            DateTime stamp = File.Exists(path) ? File.GetLastWriteTimeUtc(path) : DateTime.MinValue;
            if (Cache.TryGetValue(path, out b) && b.Stamp == stamp) return b;
            b = new Book();
            b.Stamp = stamp;
            string[] lines = stamp != DateTime.MinValue ? File.ReadAllLines(path, Encoding.UTF8) : Lang.Lines(Path.GetFileName(path), fallback);
            List<string> part = null;
            foreach (string raw in lines)
            {
                string line = raw.Trim();
                if (line.Length == 0 || line.StartsWith("#")) continue;
                if (line.StartsWith("@"))
                {
                    string name = line.Substring(1).Trim();
                    if (!b.Parts.TryGetValue(name, out part)) { part = new List<string>(); b.Parts[name] = part; }
                    continue;
                }
                if (line.StartsWith("["))
                {
                    int end = line.IndexOf(']');
                    if (end > 1)
                    {
                        string tag = line.Substring(1, end - 1);
                        List<string> list;
                        if (!b.Templates.TryGetValue(tag, out list)) { list = new List<string>(); b.Templates[tag] = list; }
                        list.Add(line.Substring(end + 1).Trim());
                    }
                    part = null;
                    continue;
                }
                if (part != null) part.Add(line);
            }
            Cache[path] = b;
            return b;
        }

        private static Book For(string dir, bool munin)
        {
            return Read(Path.Combine(dir, munin ? MuninFile : HuginFile), All(munin));
        }

        // A talk between the ravens holds together by threads: a line may start (after its tone mark) with ^thread or
        // ^one|other, what it is about or answers to. The first marked line of a talk sets the thread (ThreadGot); the
        // next lines are taken from those marked for it (ThreadWant), or from the unmarked ones when none are. Outside
        // a talk the mark is only cut off.
        // A chain: ^this>next answers "this" and moves the talk on to "next" (ThreadNext), so the following line has to
        // pick up what was just said, not only the first topic.
        internal static string ThreadWant, ThreadGot, ThreadNext;

        // what a mark answers to: the part before the arrow
        // does a mark ("a|b" or "a|b>next") answer this thread: looked at in place, no arrays made for every line tried.
        // A thread may have two levels, topic.point ("хвальба.слухає"): a line marked with the point answers just that line,
        // one marked with the bare topic ("хвальба") answers any point of it, so it has to fit every opening of the topic.
        private static bool Answers(string mark, string want)
        {
            int end = mark.IndexOf('>');
            if (end < 0) end = mark.Length;
            int dot = want.IndexOf('.');
            for (int from = 0; from <= end; )
            {
                int bar = mark.IndexOf('|', from, end - from);
                int to = bar < 0 ? end : bar;
                if (to - from == want.Length && string.CompareOrdinal(mark, from, want, 0, want.Length) == 0) return true;
                if (dot > 0 && to - from == dot && string.CompareOrdinal(mark, from, want, 0, dot) == 0) return true;
                if (bar < 0) break;
                from = bar + 1;
            }
            return false;
        }

        // the first thread a mark answers ("a" of "a|b>next")
        private static string FirstOf(string mark)
        {
            int end = 0;
            while (end < mark.Length && mark[end] != '|' && mark[end] != '>') end++;
            return end == mark.Length ? mark : mark.Substring(0, end);
        }

        // the words that must fit what is around right now (a talk sets it: no stars under a roof, no sword talk with an axe in hand); null: all fit
        internal static Func<string, bool> Fits;
        private static string TakeThread(ref string line)
        {
            if (line.Length < 2 || line[0] != '^') return null;
            int sp = line.IndexOf(' ');
            string m = sp > 1 ? line.Substring(1, sp - 1) : line.Substring(1);
            line = sp > 1 ? line.Substring(sp + 1).TrimStart() : "";
            return m.Length > 0 ? m : null;
        }

        // the same swear twice ("бля... Бля.") or a third one in a line sounds made up: such a line is put together again
        private static readonly string[][] SwearRoots =
        {
            new[] { "курв" }, new[] { "бля" }, new[] { "сук" }, new[] { "хуй", "хуя", "хує", "хуї" }, new[] { "пізд", "пизд" },
            new[] { "йоб", "йоп" }, new[] { "гівн" }, new[] { "срак", "срав", "сран" }, new[] { "мудак", "мудил", "довбойоб" },
            new[] { "трясц" }, new[] { "ядри" }, new[] { "хер", "хрін" }, new[] { "мать " }, new[] { "дуп" },
        };
        // plain words that hold a swear's letters («рахуй», «шухер», «люблять», «дупло», «тримать »): hidden before counting,
        // else an innocent line is thrown away as overcursed. «бля» and «мать» count only at the start of a word.
        private static readonly string[][] Innocent = { new[] { "рахуй", "рах_й" }, new[] { "рахує", "рах_є" }, new[] { "рахуї", "рах_ї" }, new[] { "шухер", "шух_р" }, new[] { "дупл", "д_пл" } };
        internal static string Plain(string line)
        {
            StringBuilder sb = new StringBuilder(line.ToLowerInvariant());
            foreach (string[] w in Innocent) sb.Replace(w[0], w[1]);
            string l = sb.ToString();
            foreach (string root in new[] { "бля", "мать " })
                for (int i = l.IndexOf(root, StringComparison.Ordinal); i >= 0; i = l.IndexOf(root, i + 1, StringComparison.Ordinal))
                    if (i > 0 && char.IsLetter(l[i - 1])) sb[i + 1] = '_';
            return sb.ToString();
        }

        internal static bool Overcursed(string line)
        {
            string l = Plain(line);
            int total = 0;
            foreach (string[] family in SwearRoots)
            {
                int n = 0;
                foreach (string root in family)
                    for (int i = l.IndexOf(root, StringComparison.Ordinal); i >= 0; i = l.IndexOf(root, i + root.Length, StringComparison.Ordinal)) n++;
                if (n >= 2) return true;
                total += n;
            }
            return total >= 3;
        }

        // any swear in it at all (Manner: a swearing habit only on a line that has none)
        internal static bool SwearsIn(string line)
        {
            string l = Plain(line);
            foreach (string[] family in SwearRoots)
                foreach (string root in family)
                    if (l.IndexOf(root, StringComparison.Ordinal) >= 0) return true;
            return false;
        }

        // the lists named inside a part get their pick (one level deep: parts of parts are kept simple)
        private static string Nested(Book b, string part)
        {
            if (part.IndexOf('{') < 0) return part;
            StringBuilder sb = new StringBuilder();
            int i = 0;
            while (i < part.Length)
            {
                int open = part.IndexOf('{', i);
                int close = open >= 0 ? part.IndexOf('}', open) : -1;
                if (open < 0 || close < 0) { sb.Append(part.Substring(i)); break; }
                sb.Append(part.Substring(i, open - i));
                string name = part.Substring(open + 1, close - open - 1);
                bool optional = name.EndsWith("?");
                string bare = optional ? name.Substring(0, name.Length - 1) : name;
                List<string> list;
                if (b.Parts.TryGetValue(bare, out list))
                {
                    if (!(optional && Rng.NextDouble() >= (Swears(bare) ? 0.75 : Manner.Wordy)))
                    {
                        List<string> fit = new List<string>();
                        foreach (string p in list) { string x = p; if (Tone.Take(ref x) && x.IndexOf('{') < 0 && (Fits == null || Fits(x))) fit.Add(x); }
                        if (Swears(bare)) fit = Manner.Own(fit); // Munin's own swearing
                        if (fit.Count > 0) sb.Append(Fresh(list, fit));
                        else if (!optional) return null;
                    }
                }
                else sb.Append(part.Substring(open, close - open + 1)); // a placeholder ({name}, {він|вона}): filled later
                i = close + 1;
            }
            return sb.ToString();
        }

        private static bool Swears(string list) { return list == "матюк" || list == "м_лайка" || list == "м_вигук" || list == "м_слівце"; }

        internal static bool Has(string dir, bool munin, string tag)
        {
            try { return For(dir, munin).Templates.ContainsKey(tag); }
            catch { return false; }
        }

        // a sentence for this theme, or null when no template can be filled right now
        internal static string Compose(string dir, bool munin, string tag, Dictionary<string, string> values, Func<string, bool> known) { using (Lang.Phrase()) return ComposeIn(dir, munin, tag, values, known); } // (the line's values in its own language)
        private static string ComposeIn(string dir, bool munin, string tag, Dictionary<string, string> values, Func<string, bool> known)
        {
            Book b = For(dir, munin);
            ThreadGot = null; ThreadNext = null;
            List<string> templates;
            if (!b.Templates.TryGetValue(tag, out templates) || templates.Count == 0) return null;
            List<string> fitting = new List<string>(); // the ones for this raven's tone
            foreach (string raw in templates) { string x = raw; if (Tone.Take(ref x) && Chance(ref x)) fitting.Add(x); }
            if (fitting.Count == 0) return null;
            string spare = null, spareGot = null, spareNext = null; // a line with too much swearing, if nothing better comes out
            for (int attempt = 0; attempt < 8; attempt++)
            {
                string t = Fresh(templates, fitting);
                ThreadGot = null; ThreadNext = null; // the marks of the line that is kept, not of an attempt thrown away
                string s = Expand(b, t, known);
                if (s == null || !known(s)) continue;
                if (!Overcursed(s)) return Street(munin, Tidy(Manner.Dress(s))); // this raven's habits on the line (and Munin's street mouth)
                if (spare == null) { spare = s; spareGot = ThreadGot; spareNext = ThreadNext; }
            }
            ThreadGot = spareGot; ThreadNext = spareNext;
            return spare != null ? Street(munin, Tidy(Manner.Dress(spare))) : null;
        }

        // Munin says it his way: the spoken words, a curse wedged in (Gutter; dirtier at low trust, wildest with the beast awake);
        // Hugin his: plain words, a filler now and then, a jab on the end (Gutter.Plain)
        private static string Street(bool munin, string s)
        {
            return munin ? Gutter.Dirty(s, Tone.Tier, Beast.On() && Tone.Own) : Gutter.Plain(s, Tone.Tier); // (the beast is yours: a perch's or another's raven is not rabid with it; Hugin: plain spoken, sharp)
        }

        // a template may start (after its tone mark) with %N: it is tried only N times in a hundred, so a rare kind of
        // line (the lifetime numbers) comes now and then instead of every few times
        private static bool Chance(ref string line)
        {
            string t = line.TrimStart();
            if (t.Length < 2 || t[0] != '%') return true;
            int i = 1, n = 0;
            while (i < t.Length && char.IsDigit(t[i])) { n = n * 10 + (t[i] - '0'); i++; }
            if (i == 1) return true;
            line = t.Substring(i).TrimStart();
            return Rng.Next(100) < n;
        }

        private static string Expand(Book b, string template, Func<string, bool> known)
        {
            StringBuilder sb = new StringBuilder();
            int i = 0;
            while (i < template.Length)
            {
                int open = template.IndexOf('{', i);
                if (open < 0) { sb.Append(template.Substring(i)); break; }
                int close = template.IndexOf('}', open);
                if (close < 0) { sb.Append(template.Substring(i)); break; }
                sb.Append(template.Substring(i, open - i));
                string name = template.Substring(open + 1, close - open - 1);
                bool optional = name.EndsWith("?");
                string bare = optional ? name.Substring(0, name.Length - 1) : name;
                List<string> part;
                if (b.Parts.TryGetValue(bare, out part))
                {
                    // an optional part comes half the time; Munin's swearing three times out of four (he is a foul-mouth at every trust)
                    if (!(optional && Rng.NextDouble() >= (Swears(bare) ? 0.75 : Manner.Wordy)))
                    {
                        List<string> fit = new List<string>(), loose = new List<string>();
                        Dictionary<string, string> marks = null, raw = null;
                        bool threaded = false; // the list has marked lines: in a talk its unmarked ones are never a fallback
                        foreach (string p in part)
                        {
                            string x = p;
                            if (!Tone.Take(ref x)) continue;
                            string m = TakeThread(ref x);
                            if (m != null) threaded = true;
                            if (m != null && ThreadWant != null && !Answers(m, ThreadWant)) continue; // an answer to something else (the cheap test first)
                            string written = x;
                            x = Nested(b, x);   // a list inside a part ({м_слівце}): taken right here
                            if (x == null || !known(x) || (Fits != null && !Fits(x))) continue;
                            if (x != written) { if (raw == null) raw = new Dictionary<string, string>(); raw[x] = written; }
                            if (m == null) { loose.Add(x); continue; }
                            fit.Add(x);
                            if (marks == null) marks = new Dictionary<string, string>();
                            marks[x] = m;
                        }
                        // following a talk: only the lines marked for its thread; an unmarked line answers nothing that was said
                        // (a list of noise with no marks at all, an exclamation or a swear, fits any thread; tools/talkcheck.js)
                        if (ThreadWant == null) fit.AddRange(loose); else if (fit.Count == 0 && !threaded) fit = loose;
                        if (Swears(bare)) fit = Manner.Own(fit); // Munin's own swearing
                        if (fit.Count > 0)
                        {
                            string pick = Fresh(part, fit, raw);
                            sb.Append(pick);
                            string got;
                            if (ThreadGot == null && marks != null && marks.TryGetValue(pick, out got))
                            {
                                ThreadGot = FirstOf(got);
                                int arrow = got.IndexOf('>');
                                if (arrow >= 0 && arrow + 1 < got.Length) ThreadNext = got.Substring(arrow + 1);
                            }
                        }
                        else if (!optional) return null;
                    }
                }
                else sb.Append(template.Substring(open, close - open + 1)); // a placeholder, filled later
                i = close + 1;
            }
            return sb.ToString();
        }

        // single spaces, no space before punctuation, a capital after a full stop
        private static string Tidy(string s)
        {
            StringBuilder sb = new StringBuilder();
            bool space = false;
            foreach (char c in s.Trim())
            {
                if (c == ' ') { space = true; continue; }
                if (space && sb.Length > 0 && ",.!?:;…".IndexOf(c) < 0) sb.Append(' ');
                space = false;
                sb.Append(c);
            }
            return sb.ToString();
        }

